import{_ as o,a0 as p,w as d,s as r,I as e,x as a,a1 as t,A as l,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"你所不瞭解的 Bash：關於 Bash 數組的介紹 | LCTT x X-CMD","titleTemplate":false,"description":"你所不瞭解的 Bash：關於 Bash 數組的介紹 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你所不瞭解的 Bash：關於 Bash 數組的介紹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你所不瞭解的 Bash：關於 Bash 數組的介紹 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180531 You don-t know Bash- An introduction to Bash arrays","title":"你所不瞭解的 Bash：關於 Bash 數組的介紹","tag":"201807","desc":""},"relativePath":"201807/20180531 You don-t know Bash- An introduction to Bash arrays.md","filePath":"[post].md"}'),h={name:"201807/20180531 You don-t know Bash- An introduction to Bash arrays.md"};function u(c,s,g,b,f,k){const n=p("Link");return d(),r("div",null,[s[36]||(s[36]=e("h1",{id:"你所不瞭解的-bash-關於-bash-數組的介紹",tabindex:"-1"},[a("你所不瞭解的 Bash：關於 Bash 數組的介紹 "),e("a",{class:"header-anchor",href:"#你所不瞭解的-bash-關於-bash-數組的介紹","aria-label":"Permalink to “你所不瞭解的 Bash：關於 Bash 數組的介紹”"},"​")],-1)),s[37]||(s[37]=e("blockquote",null,[e("p",null,"進入這個古怪而神奇的 Bash 數組的世界。")],-1)),s[38]||(s[38]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/programming-code-keyboard-laptop.png?itok=pGfEfu2S",alt:""})],-1)),e("p",null,[s[1]||(s[1]=a("儘管軟件工程師常常使用命令列來進行各種開發，但命令列中的數組似乎總是一個模糊的東西（雖然不像正則操作符 ",-1)),s[2]||(s[2]=e("code",null,"=~",-1)),s[3]||(s[3]=a(" 那麼複雜隱晦）。除開隱晦和有疑問的語法，",-1)),t(n,{href:"https://opensource.com/article/17/7/bash-prompt-tips-and-tricks"},{default:l(()=>[...s[0]||(s[0]=[a("Bash",-1)])]),_:1}),s[4]||(s[4]=a(" 數組其實是非常有用的。",-1))]),s[39]||(s[39]=i(`<h3 id="稍等-這是為什麼" tabindex="-1">稍等，這是為什麼？ <a class="header-anchor" href="#稍等-這是為什麼" aria-label="Permalink to “稍等，這是為什麼？”">​</a></h3><p>寫 Bash 相關的東西很難，但如果是寫一篇像手冊那樣注重怪異語法的文章，就會非常簡單。不過請放心，這篇文章的目的就是讓你不用去讀該死的使用手冊。</p><h4 id="真實-通常是有用的-示例" tabindex="-1">真實（通常是有用的）示例 <a class="header-anchor" href="#真實-通常是有用的-示例" aria-label="Permalink to “真實（通常是有用的）示例”">​</a></h4><p>為了這個目的，想像一下真實世界的場景以及 Bash 是怎麼幫忙的：你正在公司裏面主導一個新工作，評估並優化內部數據管線的運行時間。首先，你要做個參數掃描分析來評估管線使用線程的狀況。簡單起見，我們把這個管道當作一個編譯好的 C++ 黑盒子，這裏面我們能夠調整的唯一的參數是用於處理數據的線程數量：<code>./pipeline --threads 4</code>。</p><h3 id="基礎" tabindex="-1">基礎 <a class="header-anchor" href="#基礎" aria-label="Permalink to “基礎”">​</a></h3><p>我們首先要做的事是定義一個數組，用來容納我們想要測試的 <code>--threads</code> 參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>allThreads=(1 2 4 8 16 32 64 128)</span></span></code></pre></div><p>本例中，所有元素都是數字，但參數並不一定是數字，Bash 中的數組可以容納數字和字符串，比如 <code>myArray=(1 2 &quot;three&quot; 4 &quot;five&quot;)</code> 就是個有效的表達式。就像 Bash 中其它的變量一樣，確保賦值符號兩邊沒有空格。否則 Bash 將會把變量名當作程序來執行，把 <code>=</code> 當作程序的第一個參數。</p><p>現在我們初始化了數組，讓我們解析它其中的一些元素。僅僅輸入 <code>echo $allThreads</code> ，你能發現，它只會輸出第一個元素。</p><p>要理解這個產生的原因，需要回到上一步，回顧我們一般是怎麼在 Bash 中輸出變量。考慮以下場景：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type=&quot;article&quot;</span></span>
<span class="line"><span>echo &quot;Found 42 $type&quot;</span></span></code></pre></div>`,11)),e("p",null,[s[6]||(s[6]=i("假如我們得到的變量 <code>$type</code> 是一個單詞，我們想要添加在句子結尾一個 <code>s</code>。我們無法直接把 <code>s</code> 加到 <code>$type</code> 裏面，因為這會把它變成另一個變量，<code>$types</code>。儘管我們可以利用像 <code>echo &quot;Found 42 &quot;$type&quot;s&quot;</code> 這樣的代碼形變，但解決這個問題的最好方法是用一個花括號：<code>echo &quot;Found 42 ${type}s&quot;</code>，這讓我們能夠告訴 Bash 變量名的起止位置（有趣的是，JavaScript/ES6 在 ",15)),t(n,{href:"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Template_literals"},{default:l(()=>[...s[5]||(s[5]=[a("template literals",-1)])]),_:1}),s[7]||(s[7]=a(" 中注入變量和表達式的語法和這裏是一樣的）",-1))]),s[40]||(s[40]=i(`<p>事實上，儘管 Bash 變量一般不用花括號，但在數組中需要用到花括號。這反而允許我們指定要訪問的索引，例如 <code>echo \${allThreads[1]}</code> 返回的是數組中的第二個元素。如果不寫花括號，比如 <code>echo $allThreads[1]</code>，會導致 Bash 把 <code>[1]</code> 當作字符串然後輸出。</p><p>是的，Bash 數組的語法很怪，但是至少他們是從 0 開始索引的，不像有些語言（説的就是你，<code>R</code> 語言）。</p><h3 id="遍歷數組" tabindex="-1">遍歷數組 <a class="header-anchor" href="#遍歷數組" aria-label="Permalink to “遍歷數組”">​</a></h3><p>上面的例子中我們直接用整數作為數組的索引，我們現在考慮兩種其他情況：第一，如果想要數組中的第 <code>$i</code> 個元素，這裏 <code>$i</code> 是一個代表索引的變量，我們可以這樣 <code>echo \${allThreads[$i]}</code> 解析這個元素。第二，要輸出一個數組的所有元素，我們把數字索引換成 <code>@</code> 符號（你可以把 <code>@</code> 當作表示 <code>all</code> 的符號）：<code>echo \${allThreads[@]}</code>。</p><h4 id="遍歷數組元素" tabindex="-1">遍歷數組元素 <a class="header-anchor" href="#遍歷數組元素" aria-label="Permalink to “遍歷數組元素”">​</a></h4><p>記住上面講過的，我們遍歷 <code>$allThreads</code> 數組，把每個值當作 <code>--threads</code> 參數啓動管線：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for t in \${allThreads[@]}; do</span></span>
<span class="line"><span>  ./pipeline --threads $t</span></span>
<span class="line"><span>done</span></span></code></pre></div><h4 id="遍歷數組索引" tabindex="-1">遍歷數組索引 <a class="header-anchor" href="#遍歷數組索引" aria-label="Permalink to “遍歷數組索引”">​</a></h4><p>接下來，考慮一個稍稍不同的方法。不遍歷所有的數組元素，我們可以遍歷所有的索引：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for i in \${!allThreads[@]}; do</span></span>
<span class="line"><span>  ./pipeline --threads \${allThreads[$i]}</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>一步一步看：如之前所見，<code>\${allThreads[@]}</code> 表示數組中的所有元素。前面加了個感嘆號，變成 <code>\${!allThreads[@]}</code>，這會返回數組索引列表（這裏是 0 到 7）。換句話説。<code>for</code> 循環就遍歷所有的索引 <code>$i</code> 並從 <code>$allThreads</code> 中讀取第 <code>$i</code> 個元素，當作 <code>--threads</code> 選項的參數。</p><p>這看上去很辣眼睛，你可能奇怪為什麼我要一開始就講這個。這是因為有時候在循環中需要同時獲得索引和對應的值，例如，如果你想要忽視數組中的第一個元素，使用索引可以避免額外創建在循環中累加的變量。</p><h3 id="填充數組" tabindex="-1">填充數組 <a class="header-anchor" href="#填充數組" aria-label="Permalink to “填充數組”">​</a></h3><p>到目前為止，我們已經能夠用給定的 <code>--threads</code> 選項啓動管線了。現在假設按秒計時的運行時間輸出到管線。我們想要捕捉每個迭代的輸出，然後把它保存在另一個數組中，因此我們最終可以隨心所欲的操作它。</p><h4 id="一些有用的語法" tabindex="-1">一些有用的語法 <a class="header-anchor" href="#一些有用的語法" aria-label="Permalink to “一些有用的語法”">​</a></h4><p>在深入代碼前，我們要多介紹一些語法。首先，我們要能解析 Bash 命令的輸出。用這個語法可以做到：<code>output=$( ./my_script.sh )</code>，這會把命令的輸出存儲到變量 <code>$output</code> 中。</p><p>我們需要的第二個語法是如何把我們剛剛解析的值添加到數組中。完成這個任務的語法看起來很熟悉：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>myArray+=( &quot;newElement1&quot; &quot;newElement2&quot; )</span></span></code></pre></div><h4 id="參數掃描" tabindex="-1">參數掃描 <a class="header-anchor" href="#參數掃描" aria-label="Permalink to “參數掃描”">​</a></h4><p>萬事具備，執行參數掃描的腳步如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>allThreads=(1 2 4 8 16 32 64 128)</span></span>
<span class="line"><span>allRuntimes=()</span></span>
<span class="line"><span>for t in \${allThreads[@]}; do</span></span>
<span class="line"><span>  runtime=$(./pipeline --threads $t)</span></span>
<span class="line"><span>  allRuntimes+=( $runtime )</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>就是這個了！</p><h3 id="還有什麼能做的" tabindex="-1">還有什麼能做的？ <a class="header-anchor" href="#還有什麼能做的" aria-label="Permalink to “還有什麼能做的？”">​</a></h3><p>這篇文章中，我們講過使用數組進行參數掃描的場景。我敢保證有很多理由要使用 Bash 數組，這裏就有兩個例子：</p><h4 id="日誌警告" tabindex="-1">日誌警告 <a class="header-anchor" href="#日誌警告" aria-label="Permalink to “日誌警告”">​</a></h4><p>本場景中，把應用分成幾個模組，每一個都有它自己的日誌文件。我們可以編寫一個 cron 任務腳本，當某個模組中出現問題標誌時向特定的人發送郵件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 日誌列表，發生問題時應該通知的人</span></span>
<span class="line"><span>logPaths=(&quot;api.log&quot; &quot;auth.log&quot; &quot;jenkins.log&quot; &quot;data.log&quot;)</span></span>
<span class="line"><span>logEmails=(&quot;jay@email&quot; &quot;emma@email&quot; &quot;jon@email&quot; &quot;sophia@email&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 在每個日誌中查找問題標誌</span></span>
<span class="line"><span>for i in \${!logPaths[@]};</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>  log=\${logPaths[$i]}</span></span>
<span class="line"><span>  stakeholder=\${logEmails[$i]}</span></span>
<span class="line"><span>  numErrors=$( tail -n 100 &quot;$log&quot; | grep &quot;ERROR&quot; | wc -l )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  # 如果近期發現超過 5 個錯誤，就警告負責人</span></span>
<span class="line"><span>  if [[ &quot;$numErrors&quot; -gt 5 ]];</span></span>
<span class="line"><span>  then</span></span>
<span class="line"><span>    emailRecipient=&quot;$stakeholder&quot;</span></span>
<span class="line"><span>    emailSubject=&quot;WARNING: \${log} showing unusual levels of errors&quot;</span></span>
<span class="line"><span>    emailBody=&quot;\${numErrors} errors found in log \${log}&quot;</span></span>
<span class="line"><span>    echo &quot;$emailBody&quot; | mailx -s &quot;$emailSubject&quot; &quot;$emailRecipient&quot;</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>done</span></span></code></pre></div><h4 id="api-查詢" tabindex="-1">API 查詢 <a class="header-anchor" href="#api-查詢" aria-label="Permalink to “API 查詢”">​</a></h4><p>如果你想要生成一些分析數據，分析你的 Medium 帖子中用户評論最多的。由於我們無法直接訪問資料庫，SQL 不在我們考慮範圍，但我們可以用 API！</p>`,29)),e("p",null,[s[9]||(s[9]=a("為了避免陷入關於 API 授權和令牌的冗長討論，我們將會使用 ",-1)),t(n,{href:"https://github.com/typicode/jsonplaceholder"},{default:l(()=>[...s[8]||(s[8]=[a("JSONPlaceholder",-1)])]),_:1}),s[10]||(s[10]=a("，這是一個面向公眾的測試服務 API。一旦我們查詢每個帖子，解析出每個評論者的郵箱，我們就可以把這些郵箱添加到我們的結果數組裏：",-1))]),s[41]||(s[41]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>endpoint=&quot;https://jsonplaceholder.typicode.com/comments&quot;</span></span>
<span class="line"><span>allEmails=()</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查詢前 10 個帖子</span></span>
<span class="line"><span>for postId in {1..10};</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>  # 執行 API 調用，獲取該帖子評論者的郵箱</span></span>
<span class="line"><span>  response=$(curl &quot;\${endpoint}?postId=\${postId}&quot;)</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  # 使用 jq 把 JSON 響應解析成數組</span></span>
<span class="line"><span>  allEmails+=( $( jq &#39;.[].email&#39; &lt;&lt;&lt; &quot;$response&quot; ) )</span></span>
<span class="line"><span>done</span></span></code></pre></div>`,1)),e("p",null,[s[12]||(s[12]=a("注意這裏我是用 ",-1)),t(n,{href:"https://stedolan.github.io/jq/"},{default:l(()=>[...s[11]||(s[11]=[a("jq 工具",-1)])]),_:1}),s[13]||(s[13]=a(" 從命令列裏解析 JSON 數據。關於 ",-1)),s[14]||(s[14]=e("code",null,"jq",-1)),s[15]||(s[15]=a(" 的語法超出了本文的範圍，但我強烈建議你瞭解它。",-1))]),s[42]||(s[42]=i(`<p>你可能已經想到，使用 Bash 數組在數不勝數的場景中很有幫助，我希望這篇文章中的示例可以給你思維的啓發。如果你從自己的工作中找到其它的例子想要分享出來，請在帖子下方評論。</p><h3 id="請等等-還有很多東西" tabindex="-1">請等等，還有很多東西！ <a class="header-anchor" href="#請等等-還有很多東西" aria-label="Permalink to “請等等，還有很多東西！”">​</a></h3><p>由於我們在本文講了很多數組語法，這裏是關於我們講到內容的總結，包含一些還沒講到的高級技巧：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">語法</th><th style="text-align:left;">效果</th></tr></thead><tbody><tr><td style="text-align:left;"><code>arr=()</code></td><td style="text-align:left;">創建一個空數組</td></tr><tr><td style="text-align:left;"><code>arr=(1 2 3)</code></td><td style="text-align:left;">初始化數組</td></tr><tr><td style="text-align:left;"><code>\${arr[2]}</code></td><td style="text-align:left;">取得第三個元素</td></tr><tr><td style="text-align:left;"><code>\${arr[@]}</code></td><td style="text-align:left;">取得所有元素</td></tr><tr><td style="text-align:left;"><code>\${!arr[@]}</code></td><td style="text-align:left;">取得數組索引</td></tr><tr><td style="text-align:left;"><code>\${#arr[@]}</code></td><td style="text-align:left;">計算數組長度</td></tr><tr><td style="text-align:left;"><code>arr[0]=3</code></td><td style="text-align:left;">覆蓋第 1 個元素</td></tr><tr><td style="text-align:left;"><code>arr+=(4)</code></td><td style="text-align:left;">添加值</td></tr><tr><td style="text-align:left;"><code>str=$(ls)</code></td><td style="text-align:left;">把 <code>ls</code> 輸出保存到字符串</td></tr><tr><td style="text-align:left;"><code>arr=( $(ls) )</code></td><td style="text-align:left;">把 <code>ls</code> 輸出的文件保存到數組裏</td></tr><tr><td style="text-align:left;"><code>\${arr[@]:s:n}</code></td><td style="text-align:left;">取得從索引 <code>s</code> 開始的 <code>n</code> 個元素</td></tr></tbody></table></div><h3 id="最後一點思考" tabindex="-1">最後一點思考 <a class="header-anchor" href="#最後一點思考" aria-label="Permalink to “最後一點思考”">​</a></h3><p>正如我們所見，Bash 數組的語法很奇怪，但我希望這篇文章讓你相信它們很有用。只要你理解了這些語法，你會發現以後會經常使用 Bash 數組。</p><h4 id="bash-還是-python" tabindex="-1">Bash 還是 Python？ <a class="header-anchor" href="#bash-還是-python" aria-label="Permalink to “Bash 還是 Python？”">​</a></h4><p>問題來了：什麼時候該用 Bash 數組而不是其他的腳本語法，比如 Python？</p><p>對我而言，完全取決於需求——如果你可以只需要調用命令列工具就能立馬解決問題，你也可以用 Bash。但有些時候，當你的腳本屬於一個更大的 Python 項目時，你也可以用 Python。</p><p>比如，我們可以用 Python 來實現參數掃描，但我們只用編寫一個 Bash 的包裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import subprocess</span></span>
<span class="line"><span></span></span>
<span class="line"><span>all_threads = [1, 2, 4, 8, 16, 32, 64, 128]</span></span>
<span class="line"><span>all_runtimes = []</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 用不同的線程數字啓動管線</span></span>
<span class="line"><span>for t in all_threads:</span></span>
<span class="line"><span>  cmd = &#39;./pipeline --threads {}&#39;.format(t)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  # 使用子線程模組獲得返回的輸出</span></span>
<span class="line"><span>  p = subprocess.Popen(cmd, stdout=subprocess.PIPE, shell=True)</span></span>
<span class="line"><span>  output = p.communicate()[0]</span></span>
<span class="line"><span>  all_runtimes.append(output)</span></span></code></pre></div><p>由於本例中沒法避免使用命令列，所以可以優先使用 Bash。</p><h4 id="羞恥的宣傳時間" tabindex="-1">羞恥的宣傳時間 <a class="header-anchor" href="#羞恥的宣傳時間" aria-label="Permalink to “羞恥的宣傳時間”">​</a></h4>`,13)),e("p",null,[s[18]||(s[18]=a("如果你喜歡這篇文章，這裏還有很多類似的文章！ ",-1)),t(n,{href:"https://conferences.oreilly.com/oscon/oscon-or"},{default:l(()=>[...s[16]||(s[16]=[a("在此註冊，加入 OSCON",-1)])]),_:1}),s[19]||(s[19]=a("，2018 年 7 月 17 號我會在這做一個主題為 ",-1)),t(n,{href:"https://conferences.oreilly.com/oscon/oscon-or/public/schedule/detail/67166"},{default:l(()=>[...s[17]||(s[17]=[a("你所不瞭解的 Bash",-1)])]),_:1}),s[20]||(s[20]=a(" 的在線編碼研討會。沒有幻燈片，不需要門票，只有你和我在命令列裏面敲代碼，探索 Bash 中的奇妙世界。",-1))]),s[43]||(s[43]=e("p",null,"本文章由 [Medium] 首發，再發布時已獲得授權。",-1)),s[44]||(s[44]=e("hr",null,null,-1)),e("p",null,[s[22]||(s[22]=a("via: ",-1)),t(n,{href:"https://opensource.com/article/18/5/you-dont-know-bash-intro-bash-arrays"},{default:l(()=>[...s[21]||(s[21]=[a("https://opensource.com/article/18/5/you-dont-know-bash-intro-bash-arrays",-1)])]),_:1})]),e("p",null,[s[27]||(s[27]=a("作者：",-1)),t(n,{href:"https://opensource.com/users/robertaboukhalil"},{default:l(()=>[...s[23]||(s[23]=[a("Robert Aboukhalil",-1)])]),_:1}),s[28]||(s[28]=a(" 選題：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[24]||(s[24]=[a("lujun9972",-1)])]),_:1}),s[29]||(s[29]=a(" 譯者：",-1)),t(n,{href:"https://github.com/BriFuture"},{default:l(()=>[...s[25]||(s[25]=[a("BriFuture",-1)])]),_:1}),s[30]||(s[30]=a(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[26]||(s[26]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[33]||(s[33]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[31]||(s[31]=[a("LCTT",-1)])]),_:1}),s[34]||(s[34]=a(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:l(()=>[...s[32]||(s[32]=[a("Linux中國",-1)])]),_:1}),s[35]||(s[35]=a(" 榮譽推出",-1))])])}const q=o(h,[["render",u]]);export{T as __pageData,q as default};
